cat >> checks/public.cjs <<'EOF'

// Exercise visibility, permission ordering, idempotency, and failure atomicity.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owns of [false, true]) {
    for (const archived of [false, true]) {
      for (const visibility of ['visible', 'deleted', 'foreign', 'missing']) {
        const documents = [
          { id: 'target', tenant: visibility === 'foreign' ? 'b' : 'a',
            owner: owns ? 'actor' : 'other', deleted: visibility === 'deleted', archived },
          { id: 'untouched', tenant: 'a', owner: 'actor', deleted: false, archived: false },
        ];
        const repository = new DocumentRepository(documents);
        repository.audit.push({ actor: 'previous', document: 'previous' });
        const before = structuredClone({ documents, audit: repository.audit });
        const subject = new DocumentService(repository);
        const actor = { tenant: 'a', user: 'actor', role };
        const id = visibility === 'missing' ? 'absent' : 'target';
        const error = visibility !== 'visible' ? 'not found'
          : role === 'admin' || (role === 'editor' && owns) ? null : 'forbidden';
        if (error) {
          assert.throws(() => subject.archive(actor, id), { message: error });
          assert.deepEqual({ documents, audit: repository.audit }, before);
        } else {
          subject.archive(actor, id);
          const expected = structuredClone(before);
          expected.documents[0].archived = true;
          if (!archived) expected.audit.push({ actor: 'actor', document: id });
          assert.deepEqual({ documents, audit: repository.audit }, expected);
          subject.archive(actor, id);
          assert.deepEqual({ documents, audit: repository.audit }, expected);
        }
      }
    }
  }
}
EOF
tsc -p tsconfig.json && node checks/public.cjs

